 public async Task SaveAs(){if(Mode=="board"){await ExportBoard();return;}string? selected=ActionImage;if(selected==null)return;bool motion=Paths.Motion(selected);if(!motion){await SaveStillAs(selected);return;}var dialog=new SaveFileDialog{InitialDirectory=Paths.Test,FileName=motion?Path.GetFileName(selected):Path.GetFileNameWithoutExtension(selected)+(Path.GetExtension(selected).ToLowerInvariant()==".png"?".png":".jpg"),Filter=motion?"Original format|*"+Path.GetExtension(selected):"JPEG image|*.jpg|PNG image|*.png",FilterIndex=Path.GetExtension(current)==".png"?2:1};if(dialog.ShowDialog(this)!=true)return;Paths.Guard(dialog.FileName);if(string.Equals(selected,dialog.FileName,StringComparison.OrdinalIgnoreCase))throw new IOException("Choose a different path; use Crop to edit the original.");string source=selected;await Task.Run(()=>{if(motion)File.Copy(source,dialog.FileName,true);else{var image=ImageCache.Read(source,0);BitmapEncoder enc=Path.GetExtension(dialog.FileName).Equals(".png",StringComparison.OrdinalIgnoreCase)?new PngBitmapEncoder():new JpegBitmapEncoder{QualityLevel=95};enc.Frames.Add(BitmapFrame.Create(image));using var file=File.Create(dialog.FileName);enc.Save(file);}});Toast("Saved copy");}
 async Task Copy(){string? path=ActionImage;if(path==null)return;string target=Path.Combine(Paths.Data,"clipboard",Guid.NewGuid().ToString("N"),Path.GetFileName(path));Directory.CreateDirectory(Path.GetDirectoryName(target)!);await Task.Run(()=>File.Copy(path,target));var data=new DataObject();data.SetFileDropList(new StringCollection{target});if(!Paths.Motion(path)){var b=await Cache.Get(path,0);data.SetImage(b);}Clipboard.SetDataObject(data,true);Toast("Copied to Windows Clipboard");}
