 public void NormalizeBoard(){if(View.Board.Count==0)return;View.Snapshot();double targetArea=View.Board.Average(i=>i.Rect.Width*i.Rect.Height);foreach(var i in View.Board){double factor=Math.Sqrt(targetArea/(i.Rect.Width*i.Rect.Height));i.Rect=new Rect(i.Rect.Location,new Size(i.Rect.Width*factor,i.Rect.Height*factor));}View.InvalidateVisual();}
 public void PackBoard()=>CompactPack(); void OldPackBoard(){if(View.Board.Count==0)return;View.Snapshot();if(View.Board.Count==4){for(int i=0;i<4;i++){var r=View.Board[i].Rect;View.Board[i].Rect=new Rect(i%2==0?-4-r.Width:4,i<2?-4-r.Height:4,r.Width,r.Height);}var bounds=View.Board.Select(i=>i.Rect).Aggregate(Rect.Union);View.BoardScale=Math.Min((View.ActualWidth-80)/bounds.Width,(View.ActualHeight-120)/bounds.Height);View.BoardPan=new(40-bounds.X*View.BoardScale,80-bounds.Y*View.BoardScale);View.InvalidateVisual();return;}double area=View.Board.Sum(i=>i.Rect.Width*i.Rect.Height);double bound=Math.Max(View.Board.Max(i=>i.Rect.Width),Math.Sqrt(area)*1.15);double x=0,y=0,row=0;foreach(var i in View.Board.OrderByDescending(i=>i.Rect.Height)){if(x+i.Rect.Width>bound&&x>0){x=0;y+=row+8;row=0;}i.Rect=new Rect(x,y,i.Rect.Width,i.Rect.Height);x+=i.Rect.Width+8;row=Math.Max(row,i.Rect.Height);}double h=y+row;View.BoardScale=Math.Min((View.ActualWidth-80)/bound,(View.ActualHeight-140)/h);View.BoardPan=new(40,90);View.InvalidateVisual();}
