olumeUi();Config.Save();Toast(Config.Mute?"Muted":"Sound on");break;case "Diagnostics":diagnostic=!diagnostic;graph.Visibility=diagnostic?Visibility.Visible:Visibility.Collapsed;break;case "Open file":var of=new OpenFileDialog{InitialDirectory=Folder,Filter="Media|*.jpg;*.jpeg;*.png;*.gif;*.mp4;*.webm;*.bmp;*.webp;*.svg;*.heic;*.heif;*.avif;*.jp2;*.tiff;*.tif;*.ico|All files|*.*"};if(of.ShowDialog(this)==true)await Open(of.FileName);break;case "Open folder":await ChooseFolder();break;case "Collage":await StartCollage();break;case "Open file with external program":case "Open with":OpenWithMenu();break;case "Settings":ShowSettings();break;}}
